import { Directive, EffectRef, HostBinding, HostListener } from '@angular/core';

@Directive({
  selector: '[appButtonDecoration]'
})
export class ButtonDecorationDirective {

  @HostBinding('style.backgroundColor') bgColor: string | undefined;

  // ElementRef : nativeElement (property)
  constructor(private effectRef: EffectRef) { }

  ngOnInit(){
    this.effectRef.nativeElement.backgroundColor = 'yellow';
  }

  // ngOnInit(){
  //   this.bgColor = 'aqua';
  // }

  @HostListener('mouseenter') onMouseEnter(){
    this.bgColor = 'green';
  }

  @HostListener('mouseleave') onMouseLeave(){
    this.bgColor = 'aqua';
  }
}
